<?php
require_once __DIR__.'/../config/constants.php';require_admin();if(is_post()){verify_csrf();$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'Active');if($id&&in_array($status,['Active','Blocked'],true)){db()->prepare('UPDATE tbl_user SET account_status=? WHERE id=?')->execute([$status,$id]);flash('success','Customer status updated.');}redirect('admin/manage-user.php');}$q=trim((string)($_GET['q']??''));if($q!==''){$s=db()->prepare("SELECT u.*,(SELECT COUNT(*) FROM tbl_order o WHERE o.user_id=u.id) order_count,(SELECT COALESCE(SUM(total),0) FROM tbl_order o WHERE o.user_id=u.id AND o.status='Delivered') spent FROM tbl_user u WHERE u.full_name LIKE ? OR u.email LIKE ? OR u.user_name LIKE ? ORDER BY u.id DESC");$x='%'.$q.'%';$s->execute([$x,$x,$x]);$rows=$s->fetchAll();}else{$rows=db()->query("SELECT u.*,(SELECT COUNT(*) FROM tbl_order o WHERE o.user_id=u.id) order_count,(SELECT COALESCE(SUM(total),0) FROM tbl_order o WHERE o.user_id=u.id AND o.status='Delivered') spent FROM tbl_user u ORDER BY u.id DESC")->fetchAll();}$pageTitle='Customers';include __DIR__.'/partial/menu.php';?>
<div class="admin-title"><div><h1>Customers</h1><p class="muted">Search accounts and control account access.</p></div><form><div class="qty-form"><input class="input" name="q" value="<?= e($q) ?>" placeholder="Name, email, username"><button class="btn btn-light">Search</button></div></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Contact</th><th>Orders</th><th>Delivered value</th><th>Joined</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['full_name']) ?></strong><div class="muted">@<?= e($r['user_name']) ?></div></td><td><?= e($r['email']) ?><br><?= e($r['phone_number']) ?></td><td><?= (int)$r['order_count'] ?></td><td><?= e(money($r['spent'])) ?></td><td><?= e(date('M d, Y',strtotime($r['created_at']))) ?></td><td><span class="status <?= e(status_class($r['account_status'])) ?>"><?= e($r['account_status']) ?></span></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= $r['account_status']==='Active'?'Blocked':'Active' ?>"><button class="btn <?= $r['account_status']==='Active'?'btn-danger':'btn-success' ?> btn-sm" data-confirm="Change this customer account status?"><?= $r['account_status']==='Active'?'Block':'Unblock' ?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php include __DIR__.'/partial/footer.php';?>